BEGIN TRANSACTION;
CREATE TABLE audit_events (id TEXT PRIMARY KEY CHECK (typeof(id) = 'text' AND length(id) BETWEEN 1 AND 64 AND id GLOB '[a-z]*' AND id NOT GLOB '*[^a-z0-9_-]*'), kind TEXT NOT NULL CHECK (typeof(kind) = 'text' AND length(kind) BETWEEN 1 AND 64 AND kind GLOB '[a-z]*' AND kind NOT GLOB '*[^a-z0-9_-]*'), created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%d', created_at) IS NOT NULL AND strftime('%Y-%m-%d', created_at) = substr(created_at, 1, 10) AND strftime('%H:%M:%S', created_at) IS NOT NULL AND strftime('%H:%M:%S', created_at) = substr(created_at, 12, 8) AND CAST(substr(created_at, 1, 4) AS INTEGER) BETWEEN 1 AND 9999 AND CAST(substr(created_at, 12, 2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(created_at, 15, 2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(created_at, 18, 2) AS INTEGER) BETWEEN 0 AND 59), summary TEXT NOT NULL CHECK (typeof(summary) = 'text' AND summary IN ('apply completed', 'apply failed', 'apply started', 'apply verified', 'authorization denied', 'authorization granted', 'authorization revoked', 'backup failed', 'backup verified', 'decision recorded', 'discovered item', 'item changed', 'item discovered', 'item skipped', 'item unresolved', 'job completed', 'job failed', 'job queued', 'job retrying', 'job started', 'plan created', 'plan validated', 'review approved', 'review rejected', 'review requested', 'rollback completed', 'rollback failed', 'rollback started', 'verification failed', 'verification succeeded')));
CREATE TABLE current_epub_opening_evidence (target_reference TEXT NOT NULL, file_index INTEGER NOT NULL CHECK (file_index BETWEEN 0 AND 10000), evidence_id TEXT NOT NULL REFERENCES epub_opening_evidence(evidence_id), sequence INTEGER NOT NULL CHECK (sequence BETWEEN 1 AND 1000000), lane_revision INTEGER NOT NULL CHECK (lane_revision BETWEEN 1 AND 1000000), updated_at TEXT NOT NULL CHECK (typeof(updated_at) = 'text' AND length(updated_at) = 27 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) = substr(updated_at, 1, 19)), PRIMARY KEY (target_reference,file_index), UNIQUE (evidence_id));
CREATE TABLE current_inventory_observations (adapter_id TEXT NOT NULL, connection_id TEXT NOT NULL, library_id TEXT NOT NULL, external_item TEXT NOT NULL, snapshot_id TEXT NOT NULL, PRIMARY KEY (adapter_id, connection_id, library_id, external_item), FOREIGN KEY (adapter_id, connection_id, library_id, external_item, snapshot_id) REFERENCES inventory_snapshots(adapter_id, connection_id, library_id, external_item, snapshot_id));
CREATE TABLE current_inventory_snapshot_binding_sets (adapter_id TEXT NOT NULL,connection_id TEXT NOT NULL,library_id TEXT NOT NULL,external_item TEXT NOT NULL,snapshot_id TEXT NOT NULL,binding_set_digest TEXT NOT NULL REFERENCES inventory_snapshot_binding_sets(binding_set_digest),PRIMARY KEY (adapter_id,connection_id,library_id,external_item));
CREATE TABLE current_inventory_v2 (adapter_id TEXT NOT NULL, connection_id TEXT NOT NULL, library_id TEXT NOT NULL, external_item TEXT NOT NULL, snapshot_id TEXT NOT NULL, PRIMARY KEY (adapter_id, connection_id, library_id, external_item), FOREIGN KEY (adapter_id, connection_id, library_id, external_item, snapshot_id) REFERENCES inventory_v2_snapshots(adapter_id, connection_id, library_id, external_item, snapshot_id));
CREATE TABLE current_synthetic_title_proposals (lineage TEXT PRIMARY KEY, set_id TEXT NOT NULL UNIQUE, FOREIGN KEY (lineage, set_id) REFERENCES synthetic_title_proposal_sets(lineage, set_id));
CREATE TABLE current_synthetic_title_review_cases (binding_version TEXT NOT NULL CHECK (binding_version = 'synthetic-title-review-binding-v1'), adapter_id TEXT NOT NULL CHECK (adapter_id = 'synthetic-target-service'), connection_id TEXT NOT NULL CHECK (connection_id = 'synthetic-connection'), library_id TEXT NOT NULL CHECK (library_id = 'synthetic-library'), external_item TEXT NOT NULL, lineage TEXT NOT NULL, latest_set_id TEXT NOT NULL, current_case_id TEXT, sequence INTEGER NOT NULL CHECK (sequence BETWEEN 1 AND 1000000), last_transition_id TEXT NOT NULL, PRIMARY KEY (binding_version, adapter_id, connection_id, library_id, external_item, lineage), UNIQUE (binding_version, lineage), FOREIGN KEY (lineage, latest_set_id) REFERENCES synthetic_title_proposal_sets(lineage, set_id), FOREIGN KEY (binding_version, adapter_id, connection_id, library_id, external_item, lineage, current_case_id) REFERENCES synthetic_title_review_cases(binding_version, adapter_id, connection_id, library_id, external_item, lineage, case_id), FOREIGN KEY (binding_version, adapter_id, connection_id, library_id, external_item, lineage, last_transition_id) REFERENCES synthetic_title_review_case_transitions(binding_version, adapter_id, connection_id, library_id, external_item, lineage, transition_id));
CREATE TABLE epub_evidence_attempts (work_id TEXT NOT NULL REFERENCES epub_evidence_jobs(work_id), attempt INTEGER NOT NULL CHECK (attempt BETWEEN 1 AND 3), fence INTEGER NOT NULL CHECK (fence > 0), worker_id TEXT NOT NULL CHECK (length(worker_id) BETWEEN 1 AND 64), started_at TEXT NOT NULL CHECK (typeof(started_at) = 'text' AND length(started_at) = 27 AND started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', started_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', started_at) = substr(started_at, 1, 19)), finished_at TEXT CHECK (finished_at IS NULL OR (typeof(finished_at) = 'text' AND length(finished_at) = 27 AND finished_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) = substr(finished_at, 1, 19))), outcome TEXT CHECK (outcome IS NULL OR outcome IN ('success','no_applicable_evidence','unsupported_format','unsupported_version','unsupported_compression','unsupported_multiple_renditions','encrypted','malformed','integrity_failure')), failure TEXT CHECK (failure IS NULL OR failure IN ('invalid_invocation','invalid_configuration','source_reference_unavailable','ambiguous_reference','wrong_target','stale_snapshot','file_index_out_of_range','non_epub','mount_mismatch','binding_integrity_failure','corrupt_state','source_changed','busy','cancelled','timeout','resource_limit','integrity_failure','persistence_failure','internal_failure','lease_expired')), PRIMARY KEY (work_id,attempt), UNIQUE (work_id,fence));
CREATE TABLE epub_evidence_checkpoints (work_id TEXT PRIMARY KEY REFERENCES epub_evidence_jobs(work_id), attempt INTEGER NOT NULL, fence INTEGER NOT NULL, evidence_id TEXT NOT NULL REFERENCES epub_opening_evidence(evidence_id), accepted_at TEXT NOT NULL CHECK (typeof(accepted_at) = 'text' AND length(accepted_at) = 27 AND accepted_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', accepted_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', accepted_at) = substr(accepted_at, 1, 19)), FOREIGN KEY (work_id,attempt) REFERENCES epub_evidence_attempts(work_id,attempt));
CREATE TABLE epub_evidence_events (event_id TEXT PRIMARY KEY CHECK (length(event_id) BETWEEN 1 AND 64), work_id TEXT NOT NULL REFERENCES epub_evidence_jobs(work_id), kind TEXT NOT NULL CHECK (kind IN ('accepted','claimed','published','reused','failed','cancelled','retry_exhausted')), actor TEXT NOT NULL CHECK (length(actor) BETWEEN 1 AND 64), attempt INTEGER NOT NULL CHECK (attempt BETWEEN 0 AND 3), fence INTEGER NOT NULL CHECK (fence >= 0), from_state TEXT NOT NULL, to_state TEXT NOT NULL, sequence INTEGER NOT NULL CHECK (sequence BETWEEN 1 AND 1000000), occurred_at TEXT NOT NULL CHECK (typeof(occurred_at) = 'text' AND length(occurred_at) = 27 AND occurred_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) = substr(occurred_at, 1, 19)), UNIQUE (work_id,sequence));
CREATE TABLE epub_evidence_jobs (work_id TEXT PRIMARY KEY CHECK (length(work_id) BETWEEN 1 AND 64), work_key TEXT NOT NULL UNIQUE CHECK (length(work_key) = 64 AND work_key NOT GLOB '*[^0-9a-f]*'), target_reference TEXT NOT NULL CHECK (target_reference GLOB 'target_[0-9a-f]*' AND length(target_reference) = 39), snapshot_reference TEXT NOT NULL CHECK (snapshot_reference GLOB 'snapshot_[0-9a-f]*' AND length(snapshot_reference) = 41), file_index INTEGER NOT NULL CHECK (file_index BETWEEN 0 AND 10000), binding_digest TEXT NOT NULL REFERENCES inventory_snapshot_file_bindings(binding_digest), source_fingerprint TEXT NOT NULL CHECK (length(source_fingerprint) = 64 AND source_fingerprint NOT GLOB '*[^0-9a-f]*'), governing_digest TEXT NOT NULL CHECK (length(governing_digest) = 64 AND governing_digest NOT GLOB '*[^0-9a-f]*'), initiating_authority TEXT NOT NULL CHECK (length(initiating_authority) BETWEEN 1 AND 64), lane_revision INTEGER NOT NULL CHECK (lane_revision BETWEEN 1 AND 1000000), state TEXT NOT NULL CHECK (state IN ('pending','running','retry_wait','succeeded','failed_terminal','cancelled')), attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt BETWEEN 0 AND 3), max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts = 3), lease_owner TEXT CHECK (lease_owner IS NULL OR length(lease_owner) BETWEEN 1 AND 64), lease_expires_at TEXT CHECK (lease_expires_at IS NULL OR (typeof(lease_expires_at) = 'text' AND length(lease_expires_at) = 27 AND lease_expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) = substr(lease_expires_at, 1, 19))), fence INTEGER NOT NULL DEFAULT 0 CHECK (fence >= 0), cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancellation_requested IN (0,1)), terminal_outcome TEXT CHECK (terminal_outcome IS NULL OR terminal_outcome IN ('success','no_applicable_evidence','unsupported_format','unsupported_version','unsupported_compression','unsupported_multiple_renditions','encrypted','malformed','integrity_failure')), terminal_failure TEXT CHECK (terminal_failure IS NULL OR terminal_failure IN ('invalid_invocation','invalid_configuration','source_reference_unavailable','ambiguous_reference','wrong_target','stale_snapshot','file_index_out_of_range','non_epub','mount_mismatch','binding_integrity_failure','corrupt_state','source_changed','busy','cancelled','timeout','resource_limit','integrity_failure','retry_exhausted','persistence_failure','internal_failure','lease_expired')), evidence_id TEXT, created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', created_at) = substr(created_at, 1, 19)), updated_at TEXT NOT NULL CHECK (typeof(updated_at) = 'text' AND length(updated_at) = 27 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) = substr(updated_at, 1, 19)), CHECK ((state = 'running') = (lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)), CHECK ((state = 'succeeded') = (evidence_id IS NOT NULL)));
CREATE TABLE epub_opening_evidence (evidence_id TEXT PRIMARY KEY CHECK (length(evidence_id) = 41 AND evidence_id GLOB 'evidence_[0-9a-f]*'), evidence_digest TEXT NOT NULL UNIQUE CHECK (length(evidence_digest) = 64 AND evidence_digest NOT GLOB '*[^0-9a-f]*'), work_key TEXT NOT NULL UNIQUE CHECK (length(work_key) = 64 AND work_key NOT GLOB '*[^0-9a-f]*'), target_reference TEXT NOT NULL, snapshot_reference TEXT NOT NULL, file_index INTEGER NOT NULL CHECK (file_index BETWEEN 0 AND 10000), binding_digest TEXT NOT NULL REFERENCES inventory_snapshot_file_bindings(binding_digest), source_fingerprint TEXT NOT NULL CHECK (length(source_fingerprint) = 64 AND source_fingerprint NOT GLOB '*[^0-9a-f]*'), governing_digest TEXT NOT NULL CHECK (length(governing_digest) = 64 AND governing_digest NOT GLOB '*[^0-9a-f]*'), outcome TEXT NOT NULL CHECK (outcome IN ('success','no_applicable_evidence','unsupported_format','unsupported_version','unsupported_compression','unsupported_multiple_renditions','encrypted','malformed','integrity_failure')), report_json TEXT NOT NULL CHECK (length(CAST(report_json AS BLOB)) BETWEEN 2 AND 524288), report_digest TEXT NOT NULL CHECK (length(report_digest) = 64 AND report_digest NOT GLOB '*[^0-9a-f]*'), claim_count INTEGER NOT NULL CHECK (claim_count >= 0), citation_count INTEGER NOT NULL CHECK (citation_count >= 0), selected_count INTEGER NOT NULL CHECK (selected_count >= 0), rejected_count INTEGER NOT NULL CHECK (rejected_count >= 0), warning_count INTEGER NOT NULL CHECK (warning_count >= 0), package_mode TEXT NOT NULL, parser_mode TEXT NOT NULL, created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', created_at) = substr(created_at, 1, 19)));
