]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) = substr(lease_expires_at, 1, 19))), fence INTEGER NOT NULL DEFAULT 0 CHECK (fence >= 0), cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancellation_requested IN (0,1)), next_eligible_at TEXT CHECK (next_eligible_at IS NULL OR (typeof(next_eligible_at) = 'text' AND length(next_eligible_at) = 27 AND next_eligible_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', next_eligible_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', next_eligible_at) = substr(next_eligible_at, 1, 19))), failure_kind TEXT CHECK (failure_kind IS NULL OR (length(failure_kind) BETWEEN 1 AND 64 AND failure_kind NOT GLOB '*[^a-z0-9_]*')), compatibility TEXT CHECK (compatibility IS NULL OR compatibility IN ('supported','incompatible','unknown','contract_drift')), created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', created_at) = substr(created_at, 1, 19)), elapsed_deadline TEXT NOT NULL CHECK (typeof(elapsed_deadline) = 'text' AND length(elapsed_deadline) = 27 AND elapsed_deadline GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', elapsed_deadline) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', elapsed_deadline) = substr(elapsed_deadline, 1, 19)), updated_at TEXT NOT NULL CHECK (typeof(updated_at) = 'text' AND length(updated_at) = 27 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9]