CREATE TABLE inventory_scan_items (scan_id TEXT NOT NULL REFERENCES inventory_scans(scan_id), adapter_id TEXT NOT NULL, connection_id TEXT NOT NULL, library_id TEXT NOT NULL, external_item TEXT NOT NULL, snapshot_id TEXT NOT NULL, PRIMARY KEY (scan_id, external_item), FOREIGN KEY (adapter_id, connection_id, library_id, external_item, snapshot_id) REFERENCES inventory_v2_snapshots(adapter_id, connection_id, library_id, external_item, snapshot_id));
CREATE TABLE inventory_scan_poll_claims (scan_id TEXT PRIMARY KEY REFERENCES inventory_scans(scan_id), poll_id TEXT NOT NULL, attempt INTEGER NOT NULL, fence INTEGER NOT NULL CHECK (fence > 0), FOREIGN KEY (poll_id, attempt, fence) REFERENCES inventory_poll_attempts(poll_id, attempt, fence));
CREATE TABLE inventory_scans (scan_id TEXT PRIMARY KEY CHECK (typeof(scan_id) = 'text' AND length(scan_id) BETWEEN 1 AND 64), owner_id TEXT NOT NULL CHECK (typeof(owner_id) = 'text' AND length(owner_id) BETWEEN 1 AND 64), cohort_id TEXT NOT NULL CHECK (typeof(cohort_id) = 'text' AND length(cohort_id) BETWEEN 1 AND 64), cohort_size INTEGER NOT NULL CHECK (cohort_size BETWEEN 1 AND 100000), adapter_id TEXT NOT NULL CHECK (typeof(adapter_id) = 'text' AND length(adapter_id) BETWEEN 1 AND 64), connection_id TEXT NOT NULL CHECK (typeof(connection_id) = 'text' AND length(connection_id) BETWEEN 1 AND 64), library_id TEXT NOT NULL CHECK (typeof(library_id) = 'text' AND length(library_id) BETWEEN 1 AND 64), state TEXT NOT NULL CHECK (state IN ('running','complete','incomplete','unstable')), failure_kind TEXT CHECK (failure_kind IS NULL OR failure_kind IN ('authentication','authorization','unavailable','rate_limited','timeout','cancelled','unsupported','incompatible','invalid_request','invalid_response','conflict','not_found','resource_exhausted','integrity_failure','interrupted')), base_digest TEXT NOT NULL CHECK (length(base_digest) = 64 AND base_digest NOT GLOB '*[^0-9a-f]*'), page_size INTEGER NOT NULL CHECK (page_size BETWEEN 1 AND 1000), max_pages INTEGER NOT NULL CHECK (max_pages BETWEEN 1 AND 10000), max_items INTEGER NOT NULL CHECK (max_items BETWEEN 1 AND 1000000), max_bytes INTEGER NOT NULL CHECK (max_bytes BETWEEN 1024 AND 1073741824), max_seconds INTEGER NOT NULL CHECK (max_seconds BETWEEN 1 AND 3600), stability_delay_seconds INTEGER NOT NULL CHECK (stability_delay_seconds BETWEEN 0 AND 86400), page_count INTEGER NOT NULL DEFAULT 0 CHECK (page_count >= 0), item_count INTEGER NOT NULL DEFAULT 0 CHECK (item_count >= 0), response_bytes INTEGER NOT NULL DEFAULT 0 CHECK (response_bytes >= 0), started_at TEXT NOT NULL CHECK (typeof(started_at) = 'text' AND length(started_at) = 27 AND started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', started_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', started_at) = substr(started_at, 1, 19)), finished_at TEXT CHECK (finished_at IS NULL OR (typeof(finished_at) = 'text' AND length(finished_at) = 27 AND finished_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) = substr(finished_at, 1, 19))), CHECK ((state = 'running') = (finished_at IS NULL)), CHECK ((state IN ('running','complete')) = (failure_kind IS NULL)));
CREATE TABLE inventory_snapshot_binding_set_members (binding_set_digest TEXT NOT NULL REFERENCES inventory_snapshot_binding_sets(binding_set_digest),binding_digest TEXT NOT NULL REFERENCES inventory_snapshot_file_bindings(binding_digest),file_index INTEGER NOT NULL CHECK (file_index BETWEEN 0 AND 10000),PRIMARY KEY (binding_set_digest,file_index),UNIQUE (binding_set_digest,binding_digest));
CREATE TABLE inventory_snapshot_binding_sets (binding_set_digest TEXT PRIMARY KEY CHECK (length(binding_set_digest)=64 AND binding_set_digest NOT GLOB '*[^0-9a-f]*'), adapter_id TEXT NOT NULL,connection_id TEXT NOT NULL,library_id TEXT NOT NULL,external_item TEXT NOT NULL,snapshot_id TEXT NOT NULL,binding_count INTEGER NOT NULL CHECK (binding_count BETWEEN 0 AND 10001),FOREIGN KEY (adapter_id,connection_id,library_id,external_item,snapshot_id) REFERENCES inventory_v2_snapshots(adapter_id,connection_id,library_id,external_item,snapshot_id));
CREATE TABLE inventory_snapshot_file_bindings (adapter_id TEXT NOT NULL, connection_id TEXT NOT NULL, library_id TEXT NOT NULL, external_item TEXT NOT NULL, snapshot_id TEXT NOT NULL, target_reference TEXT NOT NULL CHECK (target_reference GLOB 'target_[0-9a-f]*' AND length(target_reference) = 39), snapshot_reference TEXT NOT NULL CHECK (snapshot_reference GLOB 'snapshot_[0-9a-f]*' AND length(snapshot_reference) = 41), file_index INTEGER NOT NULL CHECK (file_index BETWEEN 0 AND 10000), file_identity TEXT NOT NULL CHECK (length(file_identity) = 64 AND file_identity NOT GLOB '*[^0-9a-f]*'), media_kind TEXT NOT NULL CHECK (media_kind = 'epub'), mount_configuration_digest TEXT NOT NULL CHECK (length(mount_configuration_digest) = 64 AND mount_configuration_digest NOT GLOB '*[^0-9a-f]*'), mount_name TEXT NOT NULL CHECK (length(mount_name) BETWEEN 1 AND 64 AND mount_name NOT GLOB '*/*'), relative_path TEXT NOT NULL CHECK (length(CAST(relative_path AS BLOB)) BETWEEN 1 AND 4096 AND substr(relative_path,1,1) != '/' AND instr(relative_path,char(0)) = 0), binding_digest TEXT NOT NULL CHECK (length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), PRIMARY KEY (adapter_id,connection_id,library_id,external_item,snapshot_id,file_index,mount_configuration_digest), UNIQUE (binding_digest), UNIQUE (target_reference,snapshot_reference,file_index,mount_configuration_digest), FOREIGN KEY (adapter_id,connection_id,library_id,external_item,snapshot_id) REFERENCES inventory_v2_snapshots(adapter_id,connection_id,library_id,external_item,snapshot_id));
CREATE TABLE inventory_snapshot_locator_index (adapter_id TEXT NOT NULL,connection_id TEXT NOT NULL,library_id TEXT NOT NULL,external_item TEXT NOT NULL,snapshot_id TEXT NOT NULL,target_reference TEXT NOT NULL CHECK (target_reference GLOB 'target_[0-9a-f]*' AND length(target_reference)=39),snapshot_reference TEXT NOT NULL CHECK (snapshot_reference GLOB 'snapshot_[0-9a-f]*' AND length(snapshot_reference)=41),media_type TEXT NOT NULL CHECK (media_type IN ('ebook','audiobook')),lifecycle TEXT NOT NULL CHECK (lifecycle IN ('active','removed','unavailable')),PRIMARY KEY (adapter_id,connection_id,library_id,external_item,snapshot_id),UNIQUE (target_reference,snapshot_reference),FOREIGN KEY (adapter_id,connection_id,library_id,external_item,snapshot_id) REFERENCES inventory_v2_snapshots(adapter_id,connection_id,library_id,external_item,snapshot_id));
CREATE TABLE inventory_snapshots (adapter_id TEXT NOT NULL CHECK (typeof(adapter_id) = 'text' AND length(adapter_id) BETWEEN 1 AND 64), connection_id TEXT NOT NULL CHECK (typeof(connection_id) = 'text' AND length(connection_id) BETWEEN 1 AND 64), library_id TEXT NOT NULL CHECK (typeof(library_id) = 'text' AND length(library_id) BETWEEN 1 AND 64), external_item TEXT NOT NULL CHECK (typeof(external_item) = 'text' AND length(external_item) BETWEEN 1 AND 512), snapshot_id TEXT NOT NULL CHECK (typeof(snapshot_id) = 'text' AND length(snapshot_id) BETWEEN 1 AND 64), idempotency_operation TEXT NOT NULL CHECK (idempotency_operation = 'snapshot-store'), idempotency_digest TEXT NOT NULL CHECK (length(idempotency_digest) = 64 AND idempotency_digest NOT GLOB '*[^0-9a-f]*'), fingerprint_algorithm TEXT NOT NULL CHECK (fingerprint_algorithm = 'sha256'), fingerprint_schema TEXT NOT NULL CHECK (fingerprint_schema = 'snapshot-v1'), fingerprint_digest TEXT NOT NULL CHECK (length(fingerprint_digest) = 64 AND fingerprint_digest NOT GLOB '*[^0-9a-f]*'), canonical_input TEXT NOT NULL CHECK (typeof(canonical_input) = 'text' AND length(CAST(canonical_input AS BLOB)) BETWEEN 2 AND 1048576), observed_at TEXT NOT NULL CHECK (typeof(observed_at) = 'text' AND length(observed_at) = 27 AND observed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', observed_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', observed_at) = substr(observed_at, 1, 19)), PRIMARY KEY (adapter_id, connection_id, library_id, external_item, snapshot_id), UNIQUE (adapter_id, connection_id, library_id, external_item, idempotency_operation, idempotency_digest), UNIQUE (adapter_id, connection_id, library_id, external_item, fingerprint_schema, fingerprint_digest));
CREATE TABLE inventory_v2_snapshots (adapter_id TEXT NOT NULL CHECK (typeof(adapter_id) = 'text' AND length(adapter_id) BETWEEN 1 AND 64), connection_id TEXT NOT NULL CHECK (typeof(connection_id) = 'text' AND length(connection_id) BETWEEN 1 AND 64), library_id TEXT NOT NULL CHECK (typeof(library_id) = 'text' AND length(library_id) BETWEEN 1 AND 64), external_item TEXT NOT NULL CHECK (typeof(external_item) = 'text' AND length(external_item) BETWEEN 1 AND 512), snapshot_id TEXT NOT NULL CHECK (typeof(snapshot_id) = 'text' AND length(snapshot_id) BETWEEN 1 AND 64), fingerprint_algorithm TEXT NOT NULL CHECK (fingerprint_algorithm = 'sha256'), fingerprint_schema TEXT NOT NULL CHECK (fingerprint_schema = 'inventory-snapshot-v2'), fingerprint_digest TEXT NOT NULL CHECK (length(fingerprint_digest) = 64 AND fingerprint_digest NOT GLOB '*[^0-9a-f]*'), canonical_observation TEXT NOT NULL CHECK (typeof(canonical_observation) = 'text' AND length(CAST(canonical_observation AS BLOB)) BETWEEN 2 AND 1048576), observed_at TEXT NOT NULL CHECK (typeof(observed_at) = 'text' AND length(observed_at) = 27 AND observed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', observed_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', observed_at) = substr(observed_at, 1, 19)), PRIMARY KEY (adapter_id, connection_id, library_id, external_item, snapshot_id), UNIQUE (adapter_id, connection_id, library_id, external_item, fingerprint_schema, fingerprint_digest));
CREATE TABLE job_attempts (job_id TEXT NOT NULL REFERENCES jobs(job_id), attempt INTEGER NOT NULL CHECK (attempt BETWEEN 1 AND 2), fence INTEGER NOT NULL CHECK (fence > 0), worker_id TEXT NOT NULL CHECK (length(worker_id) BETWEEN 1 AND 64), started_at TEXT NOT NULL CHECK (typeof(started_at) = 'text' AND length(started_at) = 27 AND started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', started_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', started_at) = substr(started_at, 1, 19)), finished_at TEXT CHECK (finished_at IS NULL OR (typeof(finished_at) = 'text' AND length(finished_at) = 27 AND finished_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', finished_at) = substr(finished_at, 1, 19))), outcome TEXT CHECK (outcome IS NULL OR outcome IN ('completed')), failure TEXT CHECK (failure IS NULL OR failure IN ('synthetic_retryable','synthetic_terminal','lease_expired','dependency_failed','dependency_cancelled','invalid_dependency_outcome')), PRIMARY KEY (job_id, attempt), UNIQUE (job_id, fence));
CREATE TABLE jobs (job_id TEXT PRIMARY KEY CHECK (typeof(job_id) = 'text' AND length(job_id) BETWEEN 1 AND 64 AND job_id GLOB '[a-z]*' AND job_id NOT GLOB '*[^a-z0-9_-]*'), dedup_key TEXT NOT NULL UNIQUE CHECK (typeof(dedup_key) = 'text' AND length(dedup_key) BETWEEN 1 AND 128), run_id TEXT NOT NULL, stage_id TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('root','branch','join')), version TEXT NOT NULL CHECK (typeof(version) = 'text' AND length(version) BETWEEN 1 AND 64), state TEXT NOT NULL CHECK (state IN ('pending','leased','running','retry_wait','succeeded','failed_terminal','cancelled')), attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt BETWEEN 0 AND 2), max_attempts INTEGER NOT NULL DEFAULT 2 CHECK (max_attempts = 2), lease_owner TEXT CHECK (lease_owner IS NULL OR (length(lease_owner) BETWEEN 1 AND 64 AND lease_owner GLOB '[a-z]*' AND lease_owner NOT GLOB '*[^a-z0-9_-]*')), lease_expires_at TEXT CHECK (lease_expires_at IS NULL OR (typeof(lease_expires_at) = 'text' AND length(lease_expires_at) = 27 AND lease_expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', lease_expires_at) = substr(lease_expires_at, 1, 19))), fence INTEGER NOT NULL DEFAULT 0 CHECK (fence >= 0), cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancellation_requested IN (0,1)), next_eligible_at TEXT CHECK (next_eligible_at IS NULL OR (typeof(next_eligible_at) = 'text' AND length(next_eligible_at) = 27 AND next_eligible_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', next_eligible_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', next_eligible_at) = substr(next_eligible_at, 1, 19))), terminal_outcome TEXT CHECK (terminal_outcome IS NULL OR terminal_outcome IN ('completed')), terminal_failure TEXT CHECK (terminal_failure IS NULL OR terminal_failure IN ('synthetic_retryable','synthetic_terminal','lease_expired','dependency_failed','dependency_cancelled','invalid_dependency_outcome')), created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', created_at) = substr(created_at, 1, 19)), updated_at TEXT NOT NULL CHECK (typeof(updated_at) = 'text' AND length(updated_at) = 27 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) = substr(updated_at, 1, 19)), FOREIGN KEY (run_id, stage_id) REFERENCES workflow_stages(run_id, stage_id), UNIQUE (run_id, stage_id));
