CREATE TABLE stage_checkpoints (run_id TEXT NOT NULL, stage_id TEXT NOT NULL, source_run_id TEXT, source_stage_id TEXT, accepting_job_id TEXT REFERENCES jobs(job_id), accepting_fence INTEGER CHECK (accepting_fence IS NULL OR accepting_fence > 0), outcome TEXT NOT NULL CHECK (outcome IN ('completed')), reuse_eligible INTEGER NOT NULL CHECK (reuse_eligible IN (0,1)), current_applicable INTEGER NOT NULL CHECK (current_applicable IN (0,1)), accepted_at TEXT NOT NULL CHECK (typeof(accepted_at) = 'text' AND length(accepted_at) = 27 AND accepted_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', accepted_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', accepted_at) = substr(accepted_at, 1, 19)), PRIMARY KEY (run_id, stage_id), FOREIGN KEY (run_id, stage_id) REFERENCES workflow_stages(run_id, stage_id), FOREIGN KEY (source_run_id, source_stage_id) REFERENCES workflow_stages(run_id, stage_id), CHECK ((source_run_id IS NULL) = (source_stage_id IS NULL)), CHECK ((accepting_job_id IS NULL) = (accepting_fence IS NULL)), CHECK ((accepting_job_id IS NULL) = (source_run_id IS NOT NULL)));
CREATE TABLE synthetic_title_proposal_sets (set_id TEXT PRIMARY KEY CHECK (typeof(set_id) = 'text' AND length(set_id) BETWEEN 1 AND 64 AND set_id GLOB '[a-z]*' AND set_id NOT GLOB '*[^a-z0-9_-]*'), identity_digest TEXT NOT NULL UNIQUE CHECK (length(identity_digest) = 64 AND identity_digest NOT GLOB '*[^0-9a-f]*'), lineage TEXT NOT NULL CHECK (typeof(lineage) = 'text' AND length(lineage) BETWEEN 1 AND 64 AND lineage GLOB '[a-z]*' AND lineage NOT GLOB '*[^a-z0-9_-]*'), lineage_revision INTEGER NOT NULL CHECK (lineage_revision BETWEEN 1 AND 1000000), previous_set_id TEXT REFERENCES synthetic_title_proposal_sets(set_id), mode TEXT NOT NULL CHECK (mode = 'synthetic_preview'), canonical_set TEXT NOT NULL CHECK (typeof(canonical_set) = 'text' AND length(CAST(canonical_set AS BLOB)) BETWEEN 2 AND 131072), UNIQUE (lineage, lineage_revision), UNIQUE (lineage, set_id), CHECK (previous_set_id IS NULL OR previous_set_id != set_id));
CREATE TABLE synthetic_title_review_case_transitions (transition_id TEXT PRIMARY KEY CHECK (typeof(transition_id) = 'text' AND length(transition_id) BETWEEN 1 AND 64 AND transition_id GLOB '[a-z]*' AND transition_id NOT GLOB '*[^a-z0-9_-]*'), binding_version TEXT NOT NULL CHECK (binding_version = 'synthetic-title-review-binding-v1'), adapter_id TEXT NOT NULL CHECK (adapter_id = 'synthetic-target-service'), connection_id TEXT NOT NULL CHECK (connection_id = 'synthetic-connection'), library_id TEXT NOT NULL CHECK (library_id = 'synthetic-library'), external_item TEXT NOT NULL, lineage TEXT NOT NULL, sequence INTEGER NOT NULL CHECK (sequence BETWEEN 1 AND 1000000), successor_set_id TEXT NOT NULL, prior_case_id TEXT, replacement_case_id TEXT, kind TEXT NOT NULL CHECK (kind IN ('created','superseded','retired','no_case')), actor TEXT NOT NULL CHECK (actor = 'synthetic review admission'), reason TEXT NOT NULL CHECK (reason IN ('admit current synthetic review case','supersede current synthetic review case','retire current synthetic review case','record current synthetic no-case result')), occurred_at TEXT NOT NULL CHECK (typeof(occurred_at) = 'text' AND length(occurred_at) = 27 AND occurred_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) = substr(occurred_at, 1, 19)), UNIQUE (binding_version, lineage, successor_set_id), UNIQUE (binding_version, adapter_id, connection_id, library_id, external_item, lineage, sequence), UNIQUE (binding_version, adapter_id, connection_id, library_id, external_item, lineage, transition_id), FOREIGN KEY (lineage, successor_set_id) REFERENCES synthetic_title_proposal_sets(lineage, set_id), FOREIGN KEY (binding_version, adapter_id, connection_id, library_id, external_item, lineage, prior_case_id) REFERENCES synthetic_title_review_cases(binding_version, adapter_id, connection_id, library_id, external_item, lineage, case_id), FOREIGN KEY (binding_version, adapter_id, connection_id, library_id, external_item, lineage, replacement_case_id) REFERENCES synthetic_title_review_cases(binding_version, adapter_id, connection_id, library_id, external_item, lineage, case_id), CHECK ((kind = 'created' AND prior_case_id IS NULL AND replacement_case_id IS NOT NULL) OR (kind = 'superseded' AND prior_case_id IS NOT NULL AND replacement_case_id IS NOT NULL AND prior_case_id != replacement_case_id) OR (kind = 'retired' AND prior_case_id IS NOT NULL AND replacement_case_id IS NULL) OR (kind = 'no_case' AND prior_case_id IS NULL AND replacement_case_id IS NULL)));
CREATE TABLE synthetic_title_review_cases (case_id TEXT PRIMARY KEY CHECK (typeof(case_id) = 'text' AND length(case_id) BETWEEN 1 AND 64 AND case_id GLOB '[a-z]*' AND case_id NOT GLOB '*[^a-z0-9_-]*'), identity_digest TEXT NOT NULL UNIQUE CHECK (length(identity_digest) = 64 AND identity_digest NOT GLOB '*[^0-9a-f]*'), binding_version TEXT NOT NULL CHECK (binding_version = 'synthetic-title-review-binding-v1'), adapter_id TEXT NOT NULL CHECK (adapter_id = 'synthetic-target-service'), connection_id TEXT NOT NULL CHECK (connection_id = 'synthetic-connection'), library_id TEXT NOT NULL CHECK (library_id = 'synthetic-library'), external_item TEXT NOT NULL CHECK (typeof(external_item) = 'text' AND length(external_item) BETWEEN 1 AND 64 AND external_item GLOB '[a-z]*' AND external_item NOT GLOB '*[^a-z0-9_-]*'), target_digest TEXT NOT NULL CHECK (length(target_digest) = 64 AND target_digest NOT GLOB '*[^0-9a-f]*'), lineage TEXT NOT NULL, source_set_id TEXT NOT NULL, canonical_case TEXT NOT NULL CHECK (typeof(canonical_case) = 'text' AND length(CAST(canonical_case AS BLOB)) BETWEEN 2 AND 196608), UNIQUE (lineage, source_set_id), UNIQUE (binding_version, adapter_id, connection_id, library_id, external_item, lineage, case_id), FOREIGN KEY (lineage, source_set_id) REFERENCES synthetic_title_proposal_sets(lineage, set_id));
CREATE TABLE workflow_dependencies (run_id TEXT NOT NULL, dependent_stage_id TEXT NOT NULL, prerequisite_stage_id TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 1 CHECK (required = 1), PRIMARY KEY (run_id, dependent_stage_id, prerequisite_stage_id), FOREIGN KEY (run_id, dependent_stage_id) REFERENCES workflow_stages(run_id, stage_id), FOREIGN KEY (run_id, prerequisite_stage_id) REFERENCES workflow_stages(run_id, stage_id), CHECK (dependent_stage_id != prerequisite_stage_id));
CREATE TABLE workflow_runs (run_id TEXT PRIMARY KEY CHECK (typeof(run_id) = 'text' AND length(run_id) BETWEEN 1 AND 64 AND run_id GLOB '[a-z]*' AND run_id NOT GLOB '*[^a-z0-9_-]*'), definition_version TEXT NOT NULL CHECK (typeof(definition_version) = 'text' AND length(definition_version) BETWEEN 1 AND 64), graph_digest TEXT NOT NULL CHECK (typeof(graph_digest) = 'text' AND length(graph_digest) = 64 AND graph_digest NOT GLOB '*[^0-9a-f]*'), state TEXT NOT NULL CHECK (state IN ('waiting','running','succeeded','failed_terminal','cancelled','superseded')), cancellation_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancellation_requested IN (0,1)), replanned_from TEXT UNIQUE REFERENCES workflow_runs(run_id), superseded_by TEXT UNIQUE REFERENCES workflow_runs(run_id), created_at TEXT NOT NULL CHECK (typeof(created_at) = 'text' AND length(created_at) = 27 AND created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', created_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', created_at) = substr(created_at, 1, 19)), updated_at TEXT NOT NULL CHECK (typeof(updated_at) = 'text' AND length(updated_at) = 27 AND updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', updated_at) = substr(updated_at, 1, 19)), CHECK (replanned_from IS NULL OR replanned_from != run_id), CHECK (superseded_by IS NULL OR superseded_by != run_id));
CREATE TABLE workflow_stages (run_id TEXT NOT NULL REFERENCES workflow_runs(run_id), stage_id TEXT NOT NULL CHECK (typeof(stage_id) = 'text' AND length(stage_id) BETWEEN 1 AND 64 AND stage_id GLOB '[a-z]*' AND stage_id NOT GLOB '*[^a-z0-9_-]*'), position INTEGER NOT NULL CHECK (position BETWEEN 0 AND 31), kind TEXT NOT NULL CHECK (kind IN ('root','branch','join')), version TEXT NOT NULL CHECK (typeof(version) = 'text' AND length(version) BETWEEN 1 AND 64), expected_outcome TEXT NOT NULL CHECK (expected_outcome IN ('completed')), state TEXT NOT NULL CHECK (state IN ('waiting','ready','running','succeeded','failed_terminal','cancelled','dependency_failed','dependency_cancelled')), PRIMARY KEY (run_id, stage_id), UNIQUE (run_id, position));
CREATE TABLE workflow_transitions (transition_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES workflow_runs(run_id), sequence INTEGER NOT NULL CHECK (sequence > 0), entity_kind TEXT NOT NULL CHECK (entity_kind IN ('run','stage','job')), entity_id TEXT NOT NULL CHECK (typeof(entity_id) = 'text' AND length(entity_id) BETWEEN 1 AND 64), from_state TEXT NOT NULL CHECK (length(from_state) BETWEEN 1 AND 32), to_state TEXT NOT NULL CHECK (length(to_state) BETWEEN 1 AND 32), actor TEXT NOT NULL CHECK (actor = 'job repository'), reason TEXT NOT NULL CHECK (reason IN ('persist durable job transition','persist durable run transition','persist durable stage transition')), occurred_at TEXT NOT NULL CHECK (typeof(occurred_at) = 'text' AND length(occurred_at) = 27 AND occurred_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%S', occurred_at) = substr(occurred_at, 1, 19)), UNIQUE (run_id, sequence));
CREATE INDEX audit_events_by_created_at ON audit_events(created_at DESC, id DESC);
CREATE TRIGGER workflow_transitions_no_update BEFORE UPDATE ON workflow_transitions BEGIN SELECT RAISE(ABORT, 'workflow transitions are append-only'); END;
CREATE TRIGGER workflow_transitions_no_delete BEFORE DELETE ON workflow_transitions BEGIN SELECT RAISE(ABORT, 'workflow transitions are append-only'); END;
CREATE INDEX jobs_by_claim_eligibility ON jobs(state, next_eligible_at, created_at, job_id);
CREATE INDEX jobs_by_lease_expiry ON jobs(state, lease_expires_at, job_id);
CREATE INDEX jobs_by_run_stage ON jobs(run_id, stage_id);
CREATE INDEX workflow_dependencies_by_prerequisite ON workflow_dependencies(run_id, prerequisite_stage_id, dependent_stage_id);
CREATE INDEX workflow_runs_by_replan ON workflow_runs(replanned_from, superseded_by);
CREATE INDEX workflow_transitions_by_run ON workflow_transitions(run_id, occurred_at, transition_id);
