CREATE TRIGGER synthetic_title_review_case_transitions_no_delete BEFORE DELETE ON synthetic_title_review_case_transitions BEGIN SELECT RAISE(ABORT, 'synthetic title review transitions are append-only'); END;
CREATE TRIGGER current_synthetic_title_review_cases_no_delete BEFORE DELETE ON current_synthetic_title_review_cases BEGIN SELECT RAISE(ABORT, 'synthetic title review current state cannot be deleted'); END;
CREATE INDEX synthetic_title_review_cases_by_lineage ON synthetic_title_review_cases(lineage, source_set_id, case_id);
CREATE INDEX synthetic_title_review_transitions_by_lineage ON synthetic_title_review_case_transitions(lineage, sequence, transition_id);
